// Persistent application data uses SQLite on Android and Electron.
const databaseName = 'ofoq_travel';
let capacitorSQLite = null;
let electronDatabase = null;
let webDatabase = null;

async function initializeDatabase() {
    capacitorSQLite = window.Capacitor?.Plugins?.CapacitorSQLite || null;
    if (capacitorSQLite) {
        await capacitorSQLite.createConnection({
            database: databaseName,
            encrypted: false,
            mode: 'no-encryption',
            version: 1,
            readonly: false
        }).catch(() => {});
        await capacitorSQLite.open({ database: databaseName });
        await capacitorSQLite.execute({
            database: databaseName,
            statements: 'CREATE TABLE IF NOT EXISTS app_state (key TEXT PRIMARY KEY NOT NULL, value TEXT NOT NULL);'
        });
        return;
    }

    if (typeof require === 'function') {
        // في عملية العرض (renderer) لا تتوفر app، بل في العملية الرئيسية فقط.
        // لذلك نتحقق من وجودها قبل الاستخدام، ونكمل للبديل (IndexedDB) إن لم تتوفر.
        try {
            const { app } = require('electron');
            const { DatabaseSync } = require('node:sqlite');
            const path = require('path');
            if (app && typeof app.getPath === 'function' && DatabaseSync) {
                electronDatabase = new DatabaseSync(path.join(app.getPath('userData'), 'ofoq-travel.sqlite'));
                electronDatabase.exec('CREATE TABLE IF NOT EXISTS app_state (key TEXT PRIMARY KEY NOT NULL, value TEXT NOT NULL)');
                return;
            }
        } catch (e) {
            // فشلت تهيئة قاعدة بيانات Electron — نكمل للبديل بالأسفل
            console.warn('Electron SQLite غير متاح في هذه العملية، سيتم استخدام IndexedDB.');
        }
    }

    if (window.indexedDB) {
        webDatabase = await new Promise((resolve, reject) => {
            const request = indexedDB.open('ofoq_travel_web', 1);
            request.onupgradeneeded = () => {
                request.result.createObjectStore('app_state', { keyPath: 'key' });
            };
            request.onsuccess = () => resolve(request.result);
            request.onerror = () => reject(request.error);
        });
    }
}

async function databaseGet(key) {
    if (capacitorSQLite) {
        const result = await capacitorSQLite.query({
            database: databaseName,
            statement: 'SELECT value FROM app_state WHERE key = ?',
            values: [key]
        });
        return result.values?.[0]?.value ? JSON.parse(result.values[0].value) : null;
    }
    if (electronDatabase) {
        const row = electronDatabase.prepare('SELECT value FROM app_state WHERE key = ?').get(key);
        return row?.value ? JSON.parse(row.value) : null;
    }
    if (webDatabase) {
        const row = await new Promise((resolve, reject) => {
            const request = webDatabase.transaction('app_state', 'readonly')
                .objectStore('app_state').get(key);
            request.onsuccess = () => resolve(request.result);
            request.onerror = () => reject(request.error);
        });
        return row?.value ? JSON.parse(row.value) : null;
    }
    return null;
}

async function databaseSet(key, value) {
    const serializedValue = JSON.stringify(value);
    if (capacitorSQLite) {
        await capacitorSQLite.run({
            database: databaseName,
            statement: 'INSERT OR REPLACE INTO app_state (key, value) VALUES (?, ?)',
            values: [key, serializedValue]
        });
        return;
    }
    if (electronDatabase) {
        electronDatabase.prepare('INSERT OR REPLACE INTO app_state (key, value) VALUES (?, ?)').run(key, serializedValue);
        return;
    }
    if (webDatabase) {
        await new Promise((resolve, reject) => {
            const transaction = webDatabase.transaction('app_state', 'readwrite');
            transaction.objectStore('app_state').put({ key, value: serializedValue });
            transaction.oncomplete = resolve;
            transaction.onerror = () => reject(transaction.error);
        });
    }
}

async function databaseDelete(key) {
    if (capacitorSQLite) {
        await capacitorSQLite.run({ database: databaseName, statement: 'DELETE FROM app_state WHERE key = ?', values: [key] });
        return;
    }
    if (electronDatabase) {
        electronDatabase.prepare('DELETE FROM app_state WHERE key = ?').run(key);
        return;
    }
    if (webDatabase) {
        await new Promise((resolve, reject) => {
            const transaction = webDatabase.transaction('app_state', 'readwrite');
            transaction.objectStore('app_state').delete(key);
            transaction.oncomplete = resolve;
            transaction.onerror = () => reject(transaction.error);
        });
    }
}

