async function initializePersistentState() {
    await initializeDatabase();

    const legacySettings = JSON.parse(localStorage.getItem('ofoq_settings') || 'null');
    const legacyAirlines = JSON.parse(localStorage.getItem('savedAirlines') || localStorage.getItem('ofoq_airlines') || 'null');
    const legacyBookings = JSON.parse(localStorage.getItem('ofoq_bookings') || 'null');
    const legacyDraft = JSON.parse(localStorage.getItem('ofoq_draft') || 'null');
    const legacyPreferences = {
        lang: localStorage.getItem('ofoq_lang') || 'ar',
        currency: localStorage.getItem('ofoq_currency') || 'DZD'
    };

    const storedPreferences = await databaseGet('preferences');
    const storedSettings = await databaseGet('settings');
    const storedAirlines = await databaseGet('airlines');
    const storedBookings = await databaseGet('bookings');

    if (!storedPreferences) await databaseSet('preferences', legacyPreferences);
    if (!storedSettings && legacySettings) await databaseSet('settings', legacySettings);
    if (!storedAirlines && legacyAirlines) await databaseSet('airlines', legacyAirlines);
    if (!storedBookings && legacyBookings) await databaseSet('bookings', legacyBookings);
    if (!await databaseGet('draft') && legacyDraft) await databaseSet('draft', legacyDraft);

    currentLang = storedPreferences?.lang || legacyPreferences.lang;
    currentCurrency = storedPreferences?.currency || legacyPreferences.currency;
    companySettings = storedSettings || legacySettings || companySettings;
    const savedAirlines = storedAirlines || legacyAirlines || [];
    bookingsList = storedBookings || legacyBookings || [];

    savedAirlines.forEach(saved => {
        const existingIndex = airlinesList.findIndex(al => al.iata === saved.iata || al.name === saved.name);
        if (existingIndex !== -1) {
            if (saved.logo && saved.logo !== airlinesList[existingIndex].logo) airlinesList[existingIndex].logo = saved.logo;
        } else {
            airlinesList.push(saved);
        }
    });

    localStorage.removeItem('ofoq_settings');
    localStorage.removeItem('savedAirlines');
    localStorage.removeItem('ofoq_airlines');
    localStorage.removeItem('ofoq_bookings');
    localStorage.removeItem('ofoq_draft');
    localStorage.removeItem('ofoq_lang');
    localStorage.removeItem('ofoq_currency');
}

// Active Editing Form State
let workingPassengers = [];
let workingFlights = [];

// Initialize Application on DOM Content Loaded
document.addEventListener('DOMContentLoaded', async () => {
    await initializePersistentState();
    initLanguageAndDirection(currentLang);
    initEventListeners();
    loadSettingsIntoUI();
    renderAirlinesGrid();
    renderDashboardStats();
    renderHistoryTable();

    // Start with a new blank booking or draft recovery
    await initNewOrDraftBooking();
});

// Navigation & Sidebar

// إغلاق الشريط الجانبي للهاتف وإلغاء قفل تمرير الصفحة
function closeMobileSidebar() {
    const sb = document.getElementById('sidebar');
    if (sb) sb.classList.remove('mobile-open');
    document.body.classList.remove('sidebar-open');
}
function initEventListeners() {
    // Sidebar switching
    const navItems = document.querySelectorAll('.sidebar-nav .nav-item');
    navItems.forEach(item => {
        item.addEventListener('click', (e) => {
            e.preventDefault();
            const target = item.getAttribute('data-target');
            switchSection(target);
            navItems.forEach(nav => nav.classList.remove('active'));
            item.classList.add('active');

            // Close mobile sidebar if open
            closeMobileSidebar();
        });
    });

    document.getElementById('mobileToggleBtn').addEventListener('click', () => {
        document.getElementById('sidebar').classList.add('mobile-open');
        // منع تمرير المحتوى خلف الشريط الجانبي المفتوح على الهاتف
        document.body.classList.add('sidebar-open');
    });

    document.getElementById('mobileCloseBtn').addEventListener('click', () => {
        closeMobileSidebar();
    });

    // إغلاق الشريط الجانبي تلقائياً عند العودة لعرض سطح المكتب أو تدوير الجهاز
    window.addEventListener('resize', () => {
        if (window.innerWidth > 992) closeMobileSidebar();
    });

    // Language Selector
    const langSelector = document.getElementById('langSelector');
    langSelector.value = currentLang;
    langSelector.addEventListener('change', async (e) => {
        currentLang = e.target.value;
        await databaseSet('preferences', { lang: currentLang, currency: currentCurrency });
        initLanguageAndDirection(currentLang);
        updateLivePreview();
    });

    // Currency Selector
    const currencySelector = document.getElementById('currencySelector');
    currencySelector.value = currentCurrency;
    currencySelector.addEventListener('change', async (e) => {
        currentCurrency = e.target.value;
        await databaseSet('preferences', { lang: currentLang, currency: currentCurrency });
        updateLivePreview();
    });

    // Form inputs realtime change trigger
    const bookingForm = document.getElementById('bookingForm');
    bookingForm.addEventListener('input', () => {
        updateLivePreview();
        saveDraftBooking();
    });
    bookingForm.addEventListener('change', () => {
        updateLivePreview();
        saveDraftBooking();
    });

    // Add Passenger & Flight buttons
    document.getElementById('btnAddPassenger').addEventListener('click', () => {
        addPassengerItem();
    });

    document.getElementById('btnAddFlight').addEventListener('click', () => {
        addFlightItem();
    });

    // Save Booking
    document.getElementById('btnSaveBooking').addEventListener('click', (e) => {
        e.preventDefault();
        saveCurrentBookingToHistory();
    });

    // Reset Form
    document.getElementById('btnResetForm').addEventListener('click', (e) => {
        e.preventDefault();
        if (confirm("هل أنت متأكد من تصفير نموذج الحجز؟")) {
            resetBookingForm();
        }
    });

    // Print & PDF Export

    document.getElementById('btnPrintBooking').addEventListener('click', async () => {
        await printBookingWithLogos();
    });
    document.getElementById('btnExportPDF').addEventListener('click', () => {
        exportBookingToPDF();
    });

    // Settings Form
    document.getElementById('settingsForm').addEventListener('submit', (e) => {
        e.preventDefault();
        saveCompanySettings();
    });

    // Airline Modal
    document.getElementById('btnAddAirlineModal').addEventListener('click', () => {
        openAirlineModal(-1);
    });

    document.getElementById('closeAirlineModal').addEventListener('click', () => {
        closeAirlineModalFunc();
    });

    document.getElementById('cancelAirlineModal').addEventListener('click', () => {
        closeAirlineModalFunc();
    });

    document.getElementById('airlineForm').addEventListener('submit', (e) => {
        e.preventDefault();
        saveAirlineFromModal();
    });

    // Global Search & History Search
    document.getElementById('globalSearchInput').addEventListener('input', (e) => {
        const query = e.target.value.trim().toLowerCase();
        if (query.length > 0) {
            switchSection('section-history');
            document.getElementById('historySearchInput').value = query;
            filterHistoryTable(query);
        }
    });

    document.getElementById('historySearchInput').addEventListener('input', (e) => {
        filterHistoryTable(e.target.value.trim().toLowerCase());
    });
}

function switchSection(sectionId) {
    document.querySelectorAll('.app-section').forEach(sec => sec.classList.remove('active'));
    document.getElementById(sectionId).classList.add('active');
}

// Language and Direction Setup
function initLanguageAndDirection(lang) {
    const htmlTag = document.documentElement;
    htmlTag.setAttribute('data-lang', lang);
    if (lang === 'ar') {
        htmlTag.setAttribute('dir', 'rtl');
        htmlTag.setAttribute('lang', 'ar');
    } else {
        htmlTag.setAttribute('dir', 'ltr');
        htmlTag.setAttribute('lang', lang);
    }

    // Apply translations to static elements
    const dict = translations[lang] || translations.ar;
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (dict[key]) {
            el.textContent = dict[key];
        }
    });

    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (dict[key]) {
            el.placeholder = dict[key];
        }
    });
}

// Passenger Management
function addPassengerItem(data = null) {
    const pass = data || {
        name: "",
        gender: "Male",
        type: "Adult",
        passport: "",
        dob: ""
    };
    workingPassengers.push(pass);
    renderPassengersForm();
    updateLivePreview();
}

function removePassengerItem(index) {
    workingPassengers.splice(index, 1);
    renderPassengersForm();
    updateLivePreview();
}

function renderPassengersForm() {
    const container = document.getElementById('passengersContainer');
    container.innerHTML = '';
    const dict = translations[currentLang] || translations.ar;

    workingPassengers.forEach((pass, index) => {
        const div = document.createElement('div');
        div.className = 'dynamic-item-card';
        div.innerHTML = `
            <div class="item-card-header">
                <span>#${index + 1} - ${pass.name || (currentLang === 'ar' ? 'مسافر جديد' : 'New Passenger')}</span>
                <button type="button" class="btn-text text-danger" onclick="removePassengerItem(${index})"><i class="fa-solid fa-trash"></i></button>
            </div>
            <div class="form-grid">
                <div class="form-group">
                    <label>${dict.pass_name}</label>
                    <input type="text" class="form-control pass-name-input" value="${pass.name}" data-index="${index}" placeholder="Full Name">
                </div>
                <div class="form-group">
                    <label>${dict.pass_type}</label>
                    <select class="form-control pass-type-input" data-index="${index}">
                        <option value="Adult" ${pass.type === 'Adult' ? 'selected' : ''}>${dict.opt_adult}</option>
                        <option value="Child" ${pass.type === 'Child' ? 'selected' : ''}>${dict.opt_child}</option>
                        <option value="Infant" ${pass.type === 'Infant' ? 'selected' : ''}>${dict.opt_infant}</option>
                    </select>
                </div>
                <div class="form-group">
                    <label>${dict.pass_gender}</label>
                    <select class="form-control pass-gender-input" data-index="${index}">
                        <option value="Male" ${pass.gender === 'Male' ? 'selected' : ''}>${dict.opt_male}</option>
                        <option value="Female" ${pass.gender === 'Female' ? 'selected' : ''}>${dict.opt_female}</option>
                    </select>
                </div>
                <div class="form-group">
                    <label>${dict.pass_passport}</label>
                    <input type="text" class="form-control pass-passport-input" value="${pass.passport}" data-index="${index}" placeholder="123456789">
                </div>
                <div class="form-group">
                    <label>${dict.pass_dob}</label>
                    <input type="date" class="form-control pass-dob-input" value="${pass.dob}" data-index="${index}">
                </div>
            </div>
        `;
        container.appendChild(div);
    });

    // Attach listeners to passenger inputs
    container.querySelectorAll('.pass-name-input').forEach(input => {
        input.addEventListener('input', (e) => {
            workingPassengers[e.target.dataset.index].name = e.target.value;
            updateLivePreview();
        });
    });
    container.querySelectorAll('.pass-type-input').forEach(input => {
        input.addEventListener('change', (e) => {
            workingPassengers[e.target.dataset.index].type = e.target.value;
            updateLivePreview();
        });
    });
    container.querySelectorAll('.pass-gender-input').forEach(input => {
        input.addEventListener('change', (e) => {
            workingPassengers[e.target.dataset.index].gender = e.target.value;
            updateLivePreview();
        });
    });
    container.querySelectorAll('.pass-passport-input').forEach(input => {
        input.addEventListener('input', (e) => {
            workingPassengers[e.target.dataset.index].passport = e.target.value;
            updateLivePreview();
        });
    });
    container.querySelectorAll('.pass-dob-input').forEach(input => {
        input.addEventListener('input', (e) => {
            workingPassengers[e.target.dataset.index].dob = e.target.value;
            updateLivePreview();
        });
    });
}

// تنسيق رقم التيرمينال للعرض في التذكرة فقط: "T1" أو "1" => "T1" بدون تكرار حرف T
// ملاحظة: هذا لا يمنع الكتابة اليدوية - الحقل يبقى قابلاً للتحرير
function formatTerminal(value) {
    const t = String(value || '').trim().toUpperCase();
    if (!t) return '';
    return /^T/.test(t) ? t : `T${t}`;
}

