const bindInput = (selector, key) => {
    containerElem.querySelectorAll(selector).forEach(el => {
        el.addEventListener('input', (e) => {
            workingFlights[e.target.dataset.index][key] = e.target.value;
            updateLivePreview();
        });
    });
};
