// Calculate Flight Duration (Requirement 13)
function calculateDuration(depDate, depTime, arrDate, arrTime) {
    if (!depDate || !depTime || !arrDate || !arrTime) return "--";
    try {
        const dep = new Date(`${depDate}T${depTime}`);
        const arr = new Date(`${arrDate}T${arrTime}`);
        let diffMs = arr - dep;
        if (diffMs < 0) return "--";
        const diffHrs = Math.floor(diffMs / (1000 * 60 * 60));
        const diffMins = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
        return `${diffHrs}h ${diffMins}m`;
    } catch (e) {
        return "--";
    }
}

