// Save & Draft System
async function saveDraftBooking() {
    const draft = {
        mainTripType: document.getElementById('mainTripType').value,
        bookingStatus: document.getElementById('bookingStatus').value,
        bookingPnr: document.getElementById('bookingPnr').value,
        ticketNumber: document.getElementById('ticketNumber').value,
        bookingReference: document.getElementById('bookingReference').value,
        bookingDate: document.getElementById('bookingDate').value,
        bookingNotes: document.getElementById('bookingNotes').value,
        baseFare: document.getElementById('baseFare').value,
        taxFees: document.getElementById('taxFees').value,
        passengers: workingPassengers,
        flights: workingFlights
    };
    await databaseSet('draft', draft);
}

async function initNewOrDraftBooking() {
    const draft = await databaseGet('draft');
    if (draft && draft.bookingPnr) {
        document.getElementById('mainTripType').value = draft.mainTripType || 'One Way';
        document.getElementById('bookingStatus').value = draft.bookingStatus || 'Confirmed';
        document.getElementById('bookingPnr').value = draft.bookingPnr || '';
        document.getElementById('ticketNumber').value = draft.ticketNumber || '';
        document.getElementById('bookingReference').value = draft.bookingReference || '';
        document.getElementById('bookingDate').value = draft.bookingDate || new Date().toISOString().split('T')[0];
        document.getElementById('bookingNotes').value = draft.bookingNotes || "- يرجى الحضور إلى المطار قبل الرحلة الدولية ب 3 ساعات كاملة\n* تأكد من صلاحية جواز السفر والتأشيرة الخاصة بوجهتك\n* تحقق من وزن الأمتعة المسموح به وعدد القطع بالكبينة والشحن";
        document.getElementById('baseFare').value = draft.baseFare || '0';
        document.getElementById('taxFees').value = draft.taxFees || '0';
        workingPassengers = draft.passengers || [];
        workingFlights = draft.flights || [];
    } else {
        await resetBookingForm();
    }
    renderPassengersForm();
    renderFlightsForm();
    updateLivePreview();
}

async function resetBookingForm() {
    document.getElementById('bookingId').value = '';
    document.getElementById('mainTripType').value = 'One Way';
    document.getElementById('bookingStatus').value = 'Confirmed';
    document.getElementById('bookingPnr').value = '';
    document.getElementById('ticketNumber').value = '';
    document.getElementById('bookingReference').value = '';
    document.getElementById('bookingDate').value = new Date().toISOString().split('T')[0];
document.getElementById('bookingNotes').value = "- يرجى الحضور إلى المطار قبل الرحلة الدولية ب 3 ساعات كاملة\n- تأكد من صلاحية جواز السفر والتأشيرة الخاصة بوجهتك\n- تحقق من وزن الأمتعة المسموح به وعدد القطع بالكبينة والشحن";
    document.getElementById('baseFare').value = '0.00';
    document.getElementById('taxFees').value = '0.00';
    workingPassengers = [];
    workingFlights = [];

    // Add default 1 passenger and 1 flight
    addPassengerItem({ name: "", gender: "Male", type: "Adult", passport: "", dob: "" });
    addFlightItem();
    await databaseDelete('draft');
    updateLivePreview();
}

// Save Booking to History (Local Storage)
async function saveCurrentBookingToHistory() {
    const pnr = document.getElementById('bookingPnr').value.trim();
    if (!pnr) {
        alert("الرجاء إدخال رمز الحجز PNR على الأقل.");
        return;
    }

    const bookingId = document.getElementById('bookingId').value || 'BK-' + Date.now();
    const baseFare = parseFloat(document.getElementById('baseFare').value) || 0;
    const taxFees = parseFloat(document.getElementById('taxFees').value) || 0;

    const bookingObj = {
        id: bookingId,
        mainTripType: document.getElementById('mainTripType').value,
        bookingStatus: document.getElementById('bookingStatus').value,
        bookingPnr: pnr,
        ticketNumber: document.getElementById('ticketNumber').value,
        bookingReference: document.getElementById('bookingReference').value,
        bookingDate: document.getElementById('bookingDate').value,
        bookingNotes: document.getElementById('bookingNotes').value,
        baseFare: baseFare,
        taxFees: taxFees,
        totalPrice: baseFare + taxFees,
        currency: currentCurrency,
        passengers: [...workingPassengers],
        flights: [...workingFlights]
    };

    // Check if editing existing or adding new
    const existingIndex = bookingsList.findIndex(b => b.id === bookingId);
    if (existingIndex >= 0) {
        bookingsList[existingIndex] = bookingObj;
    } else {
        bookingsList.unshift(bookingObj);
    }

    await databaseSet('bookings', bookingsList);
    await databaseDelete('draft');

    alert("تم حفظ الحجز بنجاح وإضافته إلى السجل!");
    renderHistoryTable();
    renderDashboardStats();
    switchSection('section-history');
}

// History Table Management
function renderHistoryTable() {
    const tbody = document.getElementById('historyTableTbody');
    const dashboardTbody = document.getElementById('dashboardRecentTbody');
    tbody.innerHTML = '';
    dashboardTbody.innerHTML = '';

    if (bookingsList.length === 0) {
        tbody.innerHTML = `<tr><td colspan="8" class="text-center" style="text-align:center; padding:20px;">لا توجد حجوزات مسجلة حتى الآن</td></tr>`;
        dashboardTbody.innerHTML = `<tr><td colspan="6" class="text-center" style="text-align:center; padding:20px;">لا توجد حجوزات نشطة</td></tr>`;
        return;
    }

    bookingsList.forEach((b, index) => {
        const mainPass = b.passengers[0] ? b.passengers[0].name : '---';
        const statusClass = `status-${(b.bookingStatus || 'pending').toLowerCase().replace(/\s+/g, '')}`;

        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td><strong>${b.bookingPnr}</strong></td>
            <td>${mainPass}</td>
            <td>${b.ticketNumber || '---'}</td>
            <td>${b.mainTripType}</td>
            <td>${b.bookingDate}</td>
            <td><span class="status-badge ${statusClass}">${b.bookingStatus}</span></td>
            <td><strong>${(b.totalPrice || 0).toFixed(2)} ${b.currency || ''}</strong></td>
            <td>
                <button class="btn-icon btn-sm" onclick="editBooking('${b.id}')" title="تعديل"><i class="fa-solid fa-pen"></i></button>
                <button class="btn-icon btn-sm" onclick="loadBookingToPreview('${b.id}')" title="معاينة"><i class="fa-solid fa-eye"></i></button>
                <button class="btn-icon btn-sm text-danger" onclick="deleteBooking('${b.id}')" title="حذف"><i class="fa-solid fa-trash"></i></button>
            </td>
        `;
        tbody.appendChild(tr);

        if (index < 5) {
            const dashTr = document.createElement('tr');
            dashTr.innerHTML = `
                <td><strong>${b.bookingPnr}</strong></td>
                <td>${mainPass}</td>
                <td>${b.ticketNumber || '---'}</td>
                <td><span class="status-badge ${statusClass}">${b.bookingStatus}</span></td>
                <td><strong>${(Number(b.totalPrice) || 0).toFixed(2)} ${b.currency || ''}</strong></td>
                <td>
                    <button class="btn-icon btn-sm" onclick="loadBookingToPreview('${b.id}')" title="معاينة"><i class="fa-solid fa-eye"></i></button>
                </td>
            `;
            dashboardTbody.appendChild(dashTr);
        }
    });
}

function filterHistoryTable(query) {
    const rows = document.querySelectorAll('#historyTableTbody tr');
    rows.forEach(row => {
        const text = row.textContent.toLowerCase();
        if (text.includes(query)) {
            row.style.display = '';
        } else {
            row.style.display = 'none';
        }
    });
}

function editBooking(id) {
    const booking = bookingsList.find(b => b.id === id);
    if (!booking) return;

    document.getElementById('bookingId').value = booking.id;
    document.getElementById('mainTripType').value = booking.mainTripType;
    document.getElementById('bookingStatus').value = booking.bookingStatus;
    document.getElementById('bookingPnr').value = booking.bookingPnr;
    document.getElementById('ticketNumber').value = booking.ticketNumber;
    document.getElementById('bookingReference').value = booking.bookingReference;
    document.getElementById('bookingDate').value = booking.bookingDate;
document.getElementById('bookingNotes').value = "- يرجى الحضور إلى المطار قبل الرحلة الدولية ب 3 ساعات كاملة\n- تأكد من صلاحية جواز السفر والتأشيرة الخاصة بوجهتك\n- تحقق من وزن الأمتعة المسموح به وعدد القطع بالكبينة والشحن";
    document.getElementById('baseFare').value = booking.baseFare;
    document.getElementById('taxFees').value = booking.taxFees;
    currentCurrency = booking.currency || 'DZD';
    document.getElementById('currencySelector').value = currentCurrency;

    workingPassengers = [...booking.passengers];
    workingFlights = [...booking.flights];

    renderPassengersForm();
    renderFlightsForm();
    updateLivePreview();
    switchSection('section-new-booking');
}

function loadBookingToPreview(id) {
    editBooking(id);
}

function deleteBooking(id) {
    if (confirm("هل أنت متأكد من حذف هذا الحجز نهائياً من السجل؟")) {
        bookingsList = bookingsList.filter(b => b.id !== id);
        databaseSet('bookings', bookingsList);
        renderHistoryTable();
        renderDashboardStats();
    }
}

function renderDashboardStats() {
    document.getElementById('dashTotalBookings').textContent = bookingsList.length;
    document.getElementById('statTotalBookings').textContent = bookingsList.length;
    let totalPass = bookingsList.reduce((acc, b) => acc + b.passengers.length, 0);
    document.getElementById('dashTotalPassengers').textContent = totalPass;
    let confirmedCount = bookingsList.filter(b => b.bookingStatus === 'Confirmed').length;
    document.getElementById('dashConfirmedBookings').textContent = confirmedCount;
}

// Airlines Management
function renderAirlinesGrid() {
    const grid = document.getElementById('airlinesGridContainer');
    grid.innerHTML = '';

    airlinesList.forEach((al, index) => {
        let logoHtml = `<i class="fa-solid fa-plane"></i>`;
        if (al.logo) {
            logoHtml = `<img src="${al.logo}" class="airline-card-logo" alt="Logo">`;
        }

        const card = document.createElement('div');
        card.className = 'airline-card';
        card.innerHTML = `
            <div class="airline-card-info">
                ${logoHtml}
                <div class="airline-card-text">
                    <h4>${al.name}</h4>
                    <span>IATA: <strong>${al.iata}</strong></span>
                </div>
            </div>
            <div class="airline-card-actions">
                <button class="btn-icon btn-sm" onclick="openAirlineModal(${index})" title="تعديل"><i class="fa-solid fa-pen"></i></button>
                <button class="btn-icon btn-sm text-danger" onclick="deleteAirline(${index})" title="حذف"><i class="fa-solid fa-trash"></i></button>
            </div>
        `;
        grid.appendChild(card);
    });
}

function openAirlineModal(index) {
    document.getElementById('airlineModal').classList.add('active');
    document.getElementById('airlineEditIndex').value = index;
    const previewDiv = document.getElementById('modalLogoPreview');
    previewDiv.innerHTML = '';

    if (index >= 0) {
        const al = airlinesList[index];
        document.getElementById('airlineModalTitle').textContent = "تعديل شركة الطيران";
        document.getElementById('airlineNameInput').value = al.name;
        document.getElementById('airlineIataInput').value = al.iata;
        if (al.logo) {
            previewDiv.innerHTML = `<img src="${al.logo}" style="width:40px;height:40px;border-radius:6px;object-fit:cover;">`;
        }
    } else {
        document.getElementById('airlineModalTitle').textContent = "إضافة شركة طيران جديدة";
        document.getElementById('airlineNameInput').value = '';
        document.getElementById('airlineIataInput').value = '';
        document.getElementById('airlineLogoInput').value = '';
    }
}

function closeAirlineModalFunc() {
    document.getElementById('airlineModal').classList.remove('active');
}

function saveAirlineFromModal() {
    const index = parseInt(document.getElementById('airlineEditIndex').value);
    const name = document.getElementById('airlineNameInput').value.trim();
    const iata = document.getElementById('airlineIataInput').value.trim().toUpperCase();
    const fileInput = document.getElementById('airlineLogoInput');

    if (!name || !iata) return;

    let logoBase64 = index >= 0 ? airlinesList[index].logo : "";

    if (fileInput.files && fileInput.files[0]) {
        const reader = new FileReader();
        reader.onload = function (e) {
            logoBase64 = e.target.result;
            finishAirlineSave(index, name, iata, logoBase64);
        };
        reader.readAsDataURL(fileInput.files[0]);
    } else {
        finishAirlineSave(index, name, iata, logoBase64);
    }
}

function finishAirlineSave(index, name, iata, logo) {
    if (index >= 0) {
        airlinesList[index] = { name, iata, logo };
    } else {
        airlinesList.push({ name, iata, logo });
    }
    databaseSet('airlines', airlinesList);
    renderAirlinesGrid();
    renderFlightsForm();
    closeAirlineModalFunc();
}

function deleteAirline(index) {
    if (confirm("هل أنت متأكد من حذف شركة الطيران هذه؟")) {
        airlinesList.splice(index, 1);
        databaseSet('airlines', airlinesList);
        renderAirlinesGrid();
        renderFlightsForm();
    }
}

